#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_epilogue_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int H_out, int W_out,
    int pool_size,
    float sub1, float sub2
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int tmp   = idx / W_out;
    int h_out = tmp % H_out;
    tmp       = tmp / H_out;
    int c     = tmp % C;
    int n     = tmp / C;

    float acc  = 0.0f;
    int h_base = h_out * pool_size;
    int w_base = w_out * pool_size;

    for (int ph = 0; ph < pool_size; ph++) {
        int h_in = h_base + ph;
        if (h_in >= H) continue;
        for (int pw = 0; pw < pool_size; pw++) {
            int w_in = w_base + pw;
            if (w_in >= W) continue;
            float val = input[((n * C + c) * H + h_in) * W + w_in];
            val -= sub1;
            val  = tanhf(val);
            val -= sub2;
            acc += val;
        }
    }

    output[idx] = acc / (float)(pool_size * pool_size);
}

torch::Tensor fused_postconv_epilogue(
    torch::Tensor input,
    float sub1,
    float sub2,
    int pool_size
) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    auto inp = input.contiguous();
    TORCH_CHECK(inp.dtype() == torch::kFloat32, "input must be float32");

    const int N     = inp.size(0);
    const int C     = inp.size(1);
    const int H     = inp.size(2);
    const int W     = inp.size(3);
    const int H_out = H / pool_size;
    const int W_out = W / pool_size;

    auto output = torch::empty({N, C, H_out, W_out}, inp.options());

    const int total   = N * C * H_out * W_out;
    const int threads = 256;
    const int blocks  = (total + threads - 1) / threads;

    fused_epilogue_kernel<<<blocks, threads>>>(
        inp.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        H_out, W_out,
        pool_size,
        sub1, sub2
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a convolution, subtraction, tanh activation, subtraction and average pooling.
        """
    def __init__(self, in_channels, out_channels, kernel_size, subtract1_value, subtract2_value, kernel_size_pool):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.subtract1_value = subtract1_value
        self.subtract2_value = subtract2_value
        self.kernel_size_pool = kernel_size_pool
        self.avgpool = nn.AvgPool2d(kernel_size_pool)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        x = self.conv(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = _stark_get_extension().fused_postconv_epilogue(
            x.contiguous(), float(self.subtract1_value), float(self.subtract2_value), int(self.kernel_size_pool)
        )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        pass  # tanh fused into CUDA epilogue
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        pass  # subtract2 fused into CUDA epilogue
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        pass  # avgpool fused into CUDA epilogue
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
