CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Specialized kernel for pool_size == 2: one thread per output element,
// direct 2x2 loads, all math in registers.
__global__ void fused_epilogue_pool2_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int H_out, int W_out,
    float sub1, float sub2
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int tmp   = idx / W_out;
    int h_out = tmp % H_out;
    tmp       = tmp / H_out;
    int c     = tmp % C;
    int n     = tmp / C;

    int h_base = h_out * 2;
    int w_base = w_out * 2;

    // Base pointer for this (n, c) channel
    const float* ch_ptr = input + (n * C + c) * H * W;

    // Load all four 2x2 elements directly
    float v0 = ch_ptr[(h_base    ) * W + w_base    ];
    float v1 = ch_ptr[(h_base    ) * W + w_base + 1];
    float v2 = ch_ptr[(h_base + 1) * W + w_base    ];
    float v3 = ch_ptr[(h_base + 1) * W + w_base + 1];

    // Apply subtract -> tanh -> subtract to each element
    v0 = tanhf(v0 - sub1) - sub2;
    v1 = tanhf(v1 - sub1) - sub2;
    v2 = tanhf(v2 - sub1) - sub2;
    v3 = tanhf(v3 - sub1) - sub2;

    output[idx] = (v0 + v1 + v2 + v3) * 0.25f;
}

// Generic fallback kernel for arbitrary pool sizes
__global__ void fused_epilogue_generic_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int H_out, int W_out,
    int pool_size,
    float sub1, float sub2
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int tmp   = idx / W_out;
    int h_out = tmp % H_out;
    tmp       = tmp / H_out;
    int c     = tmp % C;
    int n     = tmp / C;

    float acc  = 0.0f;
    int h_base = h_out * pool_size;
    int w_base = w_out * pool_size;

    for (int ph = 0; ph < pool_size; ph++) {
        int h_in = h_base + ph;
        if (h_in >= H) continue;
        for (int pw = 0; pw < pool_size; pw++) {
            int w_in = w_base + pw;
            if (w_in >= W) continue;
            float val = input[((n * C + c) * H + h_in) * W + w_in];
            val -= sub1;
            val  = tanhf(val);
            val -= sub2;
            acc += val;
        }
    }

    output[idx] = acc / (float)(pool_size * pool_size);
}

torch::Tensor fused_postconv_epilogue(
    torch::Tensor input,
    float sub1,
    float sub2,
    int pool_size
) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    auto inp = input.contiguous();
